<?php
require_once __DIR__.'/../includes/functions.php'; require_role(['teacher']);
$uid=(int)current_user()['id']; $q=$conn->prepare("SELECT ts.schedule,sub.subject_code,sub.subject_name,se.year_level,se.section_name,c.code course_code FROM teachers t JOIN teacher_subjects ts ON ts.teacher_id=t.id JOIN subjects sub ON sub.id=ts.subject_id JOIN sections se ON se.id=ts.section_id JOIN courses c ON c.id=se.course_id WHERE t.user_id=? ORDER BY sub.subject_code"); $q->bind_param('i',$uid); $q->execute(); $rows=$q->get_result();
include __DIR__.'/../includes/header.php'; ?><h3 class="mb-3">My Assigned Classes</h3><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Course</th><th>Year</th><th>Section</th><th>Schedule</th></tr></thead><tbody><?php if(!$rows->num_rows): ?><tr><td colspan="5">No assigned classes found. Please contact the Registrar.</td></tr><?php else: while($r=$rows->fetch_assoc()): ?><tr><td><?=e($r['subject_code'].' - '.$r['subject_name'])?></td><td><?=e($r['course_code'])?></td><td><?=e($r['year_level'])?></td><td><?=e($r['section_name'])?></td><td><?=e($r['schedule']??'—')?></td></tr><?php endwhile; endif; ?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>